def scrub(o):
    if isinstance(o, str):
        return o.replace('—', '-').replace('–', '-')
    if isinstance(o, list):
        return [scrub(x) for x in o]
    if isinstance(o, dict):
        return {k: scrub(v) for k, v in o.items()}
    return o
out = scrub(out)

words = 0
for s in out['notes']['sections']:
    for x in s['items']:
        for key in ('f', 'c', 'trap'):
            if key in x: words += len(x[key].split())
for m in out['notes']['must']:
    words += len(m.split())
out['word_count'] = words
